import assert from \"node:assert/strict\";
import { createTenant, issueInput, useTemporaryDatabase } from \"./tests/server/_support/fixtures\";
import * as repo from \"./src/server/repositories/issue-repository\";
import * as labels from \"./src/server/repositories/label-repository\";
import * as service from \"./src/server/services/issue-service\";
import { issueFilterSchema } from \"./src/schemas/issue\";
import { exportIssuesSchema } from \"./src/schemas/export\";
import { parseIssueFilterParams, issueFilterToParams } from \"./src/hooks/issue-filter-params\";
import { ISSUE_STATUSES } from \"./src/types/issue\";
(async () => {
 const cleanup = await useTemporaryDatabase();
 try {
  const tenant = await createTenant(\"filter-smoke\");
  const orgId = tenant.org.id;
  const a = await labels.insertLabel({orgId, name: \"bug\", color: \"#000000\", description: null});
  const b = await labels.insertLabel({orgId, name: \"regression\", color: \"#000000\", description: null});
  const created = [];
  for (const [index, status] of ISSUE_STATUSES.entries()) {
   created.push(await repo.insertIssue({
    ...issueInput(orgId, tenant.project.id, {assigneeId: index % 2 ? tenant.userIds.member : null}),
    status,
    dueAt: index === 0 ? null : index === 1 ? \"2026-03-02T23:59:59.999Z\" : \"2026-03-03T00:00:00.000Z\",
    labelIds: index === 1 ? [a.id, b.id] : [a.id],
   }, tenant.userIds.owner, index + 1));
  }
  const list = (filter) => repo.listIssues({orgId, limit: 100, ...filter});
  const check = async (filter, expected) => {
   const page = await list(filter);
   assert.equal(page.total, expected);
   assert.equal(page.items.length, expected);
  };
  await check({status: [\"open\"]}, 4);
  await check({status: [\"closed\"]}, 2);
  await check({status: [\"open\", \"closed\", \"done\"]}, 6);
  await check({assigneeId: null}, 3);
  await check({labelIds: [a.id, b.id, b.id]}, 1);
  await check({dueBefore: \"2026-03-02\"}, 1);
  await check({dueBefore: \"2026-03-03T00:00:00Z\"}, 1);
  await check({dueBefore: \"2026-03-02T23:59:59.999Z\"}, 0);
  await check({dueBefore: \"2026-03-03T09:00:00+09:00\"}, 1);
  const first = await repo.listIssues({orgId, labelIds: [a.id, b.id], limit: 1});
  assert.equal(first.total, 1);
  await repo.archiveIssue(orgId, created[0].id);
  await check({}, 5);
  await check({includeArchived: true}, 6);
  await check({includeArchived: \"only\"}, 1);
  const mine = await service.listIssues(tenant.actors.member, issueFilterSchema.parse({orgId, assigneeId: \"me\"}));
  assert.equal(mine.total, 3);
  const authored = await service.listIssues(tenant.actors.owner, issueFilterSchema.parse({orgId, authorId: \"me\", includeArchived: true}));
  assert.equal(authored.total, 6);
  assert.equal(issueFilterSchema.safeParse({orgId, dueBefore: \"2026-02-30\"}).success, false);
  assert.equal(issueFilterSchema.safeParse({orgId, status: [\"unknown\"]}).success, false);
  assert.equal(exportIssuesSchema.safeParse({orgId, status: [\"open\"], includeArchived: \"only\"}).success, true);
  const decoded = parseIssueFilterParams(new URLSearchParams(\"status=open,done,unknown&assignee=me&author=me&archived=only&due_before=2026-03-02\"));
  assert.equal(decoded.status.length, 5);
  assert.equal(decoded.assigneeId, \"me\");
  assert.equal(decoded.authorId, \"me\");
  assert.equal(issueFilterToParams(decoded).archived, \"only\");
  assert.equal(issueFilterSchema.safeParse({orgId, ...decoded}).success, true);
  console.log(\"Filter smoke checks passed\");
 } finally { cleanup(); }
})();
'"

